import styled from '@emotion/styled';

interface StickyScrollCollapseStylesProps {
  $show?: boolean;
}

export const StickyScrollCollapseStyles =
  styled.div<StickyScrollCollapseStylesProps>(({ $show }) => ({
    display: 'grid',
    transition: 'grid-template-rows 0.2s ease, opacity 0.2s ease',

    '& > *': {
      overflow: 'hidden',
    },

    ...($show === true && {
      opacity: 1,
      gridTemplateRows: '1fr',
    }),
    ...($show === false && {
      opacity: 0,
      gridTemplateRows: '0fr',
      pointerEvents: 'none',
      paddingBottom: 0,
    }),
  }));
